import {WORKOUT_NAMES} from './training.mjs';
const extrasEscape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const WEEK_ROW_LABELS={completed:'全部组完成',trained:'部分完成',recorded:'已填待确认',pending:'待训练',unrecorded:'未记录',paused:'暂停',rest:'恢复日'};
export function renderTrainingWeek(w,detail=false){
  const actual=w.trainedSessions>0;
  return `<section class="card training-week mt" id="training-week-summary"><div class="card-title"><div><p class="eyebrow">YOUR WEEK, YOUR ACTUAL WORK</p><h2>本周训练复盘</h2><p class="micro-note">${w.monday} — ${w.end} · 周一至周日</p></div><span class="tag">${w.percent}% 全周组进度</span></div><div class="week-training-metrics"><div><b>${w.trainedSessions}<small> / ${w.plannedSessions} 次</small></b><span>实际练过 / 纳入计划</span></div><div><b>${w.completedSessions}<small> 次</small></b><span>全部计划组完成</span></div><div><b>${w.completedSets}<small> / ${w.plannedSets} 组</small></b><span>实际完成 · 跳过${w.skippedSets}组</span></div><div><b>${actual?w.totalReps:'—'}<small>${actual?' 次':''}</small></b><span>已确认实际累计次数</span></div></div><p class="micro-note">完整周的计划组都计入分母；未来训练显示待训练。结束记录不会把部分训练算作全部完成。</p>${detail?renderTrainingWeekRows(w):`<details class="week-training-details"><summary>查看每天实际情况</summary>${renderTrainingWeekRows(w)}</details>`}</section>`;
}
export function renderTrainingWeekRows(w){
  return `<div class="training-week-days">${w.rows.map(row=>`<button class="training-week-day" data-date="${row.date}" data-go-training="true"><span><b>${row.date.slice(5).replace('-','.')}</b><small>${extrasEscape(WORKOUT_NAMES[row.type]||'恢复')}</small></span><span>${row.plannedSets?`${row.completedSets}/${row.plannedSets}组 · ${row.percent}%`:'—'}<small>${WEEK_ROW_LABELS[row.status]||'未记录'}${row.skippedSets?` · 跳过${row.skippedSets}组`:''}</small></span><span aria-hidden="true">↗</span></button>`).join('')}</div>`;
}
export function renderRestTimerBar(){return `<aside class="rest-timer-bar" id="rest-timer-bar" hidden aria-label="组间休息倒计时"><div class="rest-timer-top"><div><span id="rest-timer-label">组间休息</span><b id="rest-timer-clock" role="timer" aria-live="off">02:00</b></div><div class="rest-presets" aria-label="选择休息秒数">${[60,90,120].map(s=>`<button type="button" data-action="rest-preset" data-seconds="${s}">${s}秒</button>`).join('')}</div></div><div class="rest-controls"><button class="secondary" data-action="rest-toggle" id="rest-toggle">暂停</button><button class="text-button" data-action="rest-reset">重置</button><button class="text-button" data-action="rest-close" aria-label="关闭休息倒计时">关闭</button><span id="rest-timer-state" role="status" aria-live="polite"></span></div></aside>`;}
